const phases=['morning','lunch','afternoon','evening'],beatTypes={morning:'task',lunch:'relationship',afternoon:'decision',evening:'private_consequence'};const threadIds=['artistic_intention_and_readability','body_consent_and_movement','director_choreographer_alignment','technical_safety_and_integration','version_handoff_and_rework','ensemble_power_and_note_culture','private_status_and_recovery'];const audIds=audiences.map(x=>x.id),coverage=[];
for(let d=1;d<=14;d++)for(let pi=0;pi<4;pi++){const ph=phases[pi],[title,problem]=days[d-1],aud=audIds[(d+pi-1)%audIds.length],ref=sourceRefs[((d-1)*4+pi)%sourceRefs.length],thread=threadIds[(d+pi-1)%threadIds.length];const phaseWork=ph==='morning'?'Morgenen etablerer hva som faktisk er observert, hvilken sceneversjon som gjelder og hvilke premisser som fortsatt venter på svar før tempoet i prøvedagen kan gjøre antakelser til sannhet.':ph==='lunch'?'Ved lunsj prøves retningen i en konkret arbeidsrelasjon: motstemme, usikkerhet og asymmetri skal kunne uttrykkes uten at framtidige roller, status eller tilgang brukes som pressmiddel.':ph==='afternoon'?'I ettermiddagen må et kunstnerisk valg, en avgrensning eller en handoff faktisk gjøres, men det skal være lesbart hvem som eier beslutningen, hva som er betinget og hva som må retestes.':'Om kvelden kommer den mindre synlige kostnaden fram: kroppslig slitasje, statusangst, tvil eller lettelse. Privat ettervirkning holdes adskilt fra fortrolige utøverdata og neste dags formelle evidens.';const base=`Dag ${d}, ${ph}: ${title}. ${problem} ${phaseWork} Spilleren må skille kunstnerisk intensjon, konkret prøveobservasjon, utøverens samtykke og belastningsgrense, teknisk sikkerhetsstatus, rettighetsstatus og den versjonen ensemble, inspisient og teknikk faktisk har mottatt. Alt som endrer handlingsrommet føres i den eksisterende \`proveromsbok_og_scenisk_beslutningslogg\` med scenemål, versjon, kilde til observasjonen, beslutningseier, venting, handoff, berørt kropp/rom/teknikk/rettighet, konkret retest og tidspunkt for ny kontroll. En kunstnerisk note er derfor ikke det samme som samtykke, en teknisk skisse er ikke sikkerhetsgodkjenning, og en vellykket gjennomkjøring gjør ikke et uavklart rettighets- eller arbeidsmiljøproblem ferdig. Denne dagen må også vise hvem som bærer kostnaden når rework kommer sent, hvilke tidligere valg som fortsatt kan beholdes, og hvordan regi og koreografi kan endre virkemiddel uten å late som det opprinnelige målet forsvant. Neste aktør skal kunne se hva som er sant nå, hva som fortsatt kan bestrides, hvem som må svare og hvilke vilkår som må være oppfylt før status løftes. Beat-en bruker den allerede authored mail-/arbeidsgrammatikken som materialisering og introduserer ingen ny dagsmotor, global reputation-runtime, samtykkemotor eller skjult autoritetsakse.`;const a=audiences.find(x=>x.id===aud);const sc=`Situert standing på dag ${d}, ${ph}, vurderes hos \`${aud}\` langs aksen \`${a.standing_axis}\`. Her teller ${a.cares_about.join(' og ')}. Standing styrkes når spilleren gjør mål, versjon, samtykke/HMS, tekniske og rettslige premisser, beslutningseier, effektkontroll og reparerbarhet synlige, og svekkes når prestisje, premierepress, fysisk intensitet eller kunstnerisk status brukes til å skyve usikkerhet og kostnad over på andre. ${a.cannot_grant} Standing gjelder bare denne konkrete relasjonen og prøvesituasjonen; den summeres aldri til en global reputation score, kan gå i motsatt retning hos andre publikum og kan senere endres når retest, utøversvar, teknisk prøve, rettighetsavklaring, gjennomløp eller offentlig møte gir ny evidens. En god relasjon i ett rom kan ikke brukes som bevis på tillit eller fullmakt i et annet, og applaus kan ikke retroaktivt legitimere en uforsvarlig arbeidsprosess.`;coverage.push({day:d,phase:ph,beat_type:beatTypes[ph],summary:base,thread_ids:[thread],materialization_refs:[ref],standing_audience:aud,standing_consequence:sc})}
