const TEST=`const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const R=path.resolve(__dirname,'..'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p))),KEY='${KEY}',ROLE='${ROLE}',WORLD='${WORLD}',PLAN='${PLAN}',MODEL='${MODEL}',GRAMMAR='${GRAMMAR}';const world=read(WORLD);assert.equal(world.schema,'civication_role_world_v1');assert.equal(world.status,'role_world_complete');assert.deepEqual(world.materialization.authored_dimensions,['situated_reputation']);for(const k of ['no_new_runtime','existing_plan_preserved','existing_role_model_preserved','existing_people_foundation_preserved','existing_work_grammar_preserved','existing_persistent_work_preserved','existing_rhythm_preserved'])assert.equal(world.materialization[k],true,k);assert.equal(world.materialization.cross_role_link_materialized,false);assert.deepEqual(world.existing_work_continuity.work_loops,read(GRAMMAR).work_loops);assert.equal(world.existing_work_continuity.persistent_work_object,'proveromsbok_og_scenisk_beslutningslogg');assert.equal(world.existing_work_continuity.new_runtime_state,false);assert.equal(read(PLAN).sequence.length,16);for(const p of read(MODEL).related_people){assert.equal(p.fictional,true);assert.equal(p.fictional_scenario_actor,true);assert.equal(p.canonical_person_ref,null)}const refs=world.materialization.source_refs;assert.equal(refs.length,15);assert.equal(new Set(refs).size,15);for(const ref of refs){const[f,id]=ref.split('#');assert.ok(read(f).families.flatMap(x=>x.mails||[]).some(m=>m.id===id),ref)}const audienceIds=${JSON.stringify(audIds)};assert.equal(world.situated_reputation_model.global_score_allowed,false);assert.deepEqual(world.situated_reputation_model.audiences.map(a=>a.id),audienceIds);for(const a of world.situated_reputation_model.audiences){assert.ok(a.cares_about.length>=2);assert.match(a.cannot_grant,/ikke|kan ikke/i)}for(const term of [/samtykke/i,/HMS/i,/teknisk/i,/rettighet/i,/mandat/i])assert.match(world.situated_reputation_model.authority_separation,term);assert.ok(refs.includes(world.history_go_affordance.source_ref));assert.ok(world.history_go_affordance.better_question.length>=220);assert.match(world.history_go_affordance.better_question,/Edith Roger/);assert.match(world.history_go_affordance.better_question,/Nationaltheatret/);assert.match(world.history_go_affordance.authority_boundary,/ikke|kan ikke/i);assert.equal(world.cross_role_link.status,'candidate_when_shared_work_is_real');assert.equal(world.cross_role_link.materialized,false);assert.equal(world.cross_role_link.new_runtime,false);assert.equal('shared_work_object'in world.cross_role_link,false);assert.match(world.cross_role_link.rule,/candidate_when_shared_work_is_real/);assert.equal(world.season.days,14);assert.deepEqual(world.season.day_phases,['morning','lunch','afternoon','evening']);assert.equal(world.season.coverage.length,56);const beatKeys=new Set(world.season.coverage.map(b=>b.day+'/'+b.phase));assert.equal(beatKeys.size,56);assert.equal(new Set(world.season.coverage.map(b=>b.summary)).size,56);assert.equal(new Set(world.season.coverage.map(b=>b.standing_consequence)).size,56);const uses=new Map(refs.map(r=>[r,0]));for(const b of world.season.coverage){assert.ok(b.summary.length>=620,b.day+'/'+b.phase+' summary');assert.ok(b.standing_consequence.length>=500,b.day+'/'+b.phase+' consequence');assert.ok(audienceIds.includes(b.standing_audience));assert.equal(b.materialization_refs.length,1);assert.ok(refs.includes(b.materialization_refs[0]));uses.set(b.materialization_refs[0],uses.get(b.materialization_refs[0])+1)}for(const[r,n]of uses)assert.ok(n>=3,r+' underused '+n);assert.equal(world.primary_threads.length,7);for(const t of world.primary_threads){assert.ok(t.relationship.length>=160);assert.ok(t.beat_refs.length>=5&&t.beat_refs.length<=10);assert.ok(new Set(t.beat_refs.map(r=>r.split('/')[0])).size>=3);for(const r of t.beat_refs)assert.ok(beatKeys.has(r),r)}assert.equal(world.private_aftermath.length,5);for(const x of world.private_aftermath){assert.equal(new Set(x.beat_refs).size,x.beat_refs.length);assert.ok(x.meaning.length>=140);for(const r of x.beat_refs)assert.ok(beatKeys.has(r),r)}assert.equal(world.delayed_consequences.length,8);for(const x of world.delayed_consequences){assert.ok(beatKeys.has(x.setup_ref));assert.ok(beatKeys.has(x.return_ref));assert.ok(Number(x.return_ref.split('/')[0])>Number(x.setup_ref.split('/')[0]))}const index=read('data/Civication/roleWorlds/index.json');assert.deepEqual(index.roles.find(e=>e.category==='scenekunst'&&e.role_scope===ROLE),{category:'scenekunst',role_scope:ROLE,status:'role_world_complete',path:WORLD});assert.match(index.status,/_role_worlds_materialized$/);assert.ok(read('data/Civication/roleWorldAuthoringChecklist.json').reference_worlds.includes(WORLD));assert.deepEqual(read('data/Civication/roleWorldThemeBank.json').reference_profiles[KEY],world.theme_ids);const readiness=read('data/Civication/roleWorldRolloutReadiness.json');assert.ok(!(readiness.rollout_queue||[]).some(e=>e.key===KEY));assert.equal(readiness.roles.find(e=>e.key===KEY).role_world_status,'role_world_complete');assert.ok(readiness.summary.role_world_complete_or_pilot>=49);assert.equal(readiness.gate.gate_pass,true);const career=read('data/Civication/careerGameplayMatrix.json').worlds.find(e=>e.key===KEY);assert.equal(career.status,'playable');assert.equal(career.audit.runtime_gate,true);assert.deepEqual(career.audit.missing_components,[]);const source=fs.readFileSync(path.join(R,'reports/CIVICATION_SCENEKUNST_REGI_OG_KOREOGRAFI_ROLE_WORLD_ROLLOUT_SOURCE_FIRST.md'),'utf8');assert.match(source,/Editorial uniqueness/i);assert.match(source,/global reputation score/i);assert.match(source,/candidate_when_shared_work_is_real/);assert.match(source,/29\\/30/);console.log('Civication Scenekunst Regi og koreografi Role World rollout: OK');`;T('tests/civication-scenekunst-regi-og-koreografi-role-world-rollout.test.js',TEST);T('reports/CIVICATION_SCENEKUNST_REGI_OG_KOREOGRAFI_ROLE_WORLD_ROLLOUT_SOURCE_FIRST.md',`# Civication — Scenekunst Regi og koreografi Role World rollout\n\n## Scope lock\n- Canonical role: \`${KEY}\`.\n- Prerequisites are already merged; this PR authors only the dedicated Role World depth.\n- Existing appointment, role model, grammar, 16-step plan, four fictional actors, four work surfaces, all 15 mails and \`proveromsbok_og_scenisk_beslutningslogg\` remain authoritative.\n- No new runtime system, parallel scene format, consent engine or global reputation score is introduced.\n\n## Editorial uniqueness\nThis season is authored around the social mechanics of a rehearsal room: artistic authority, bodily consent, performer load, director/choreographer alignment, stage-management version control, technical safety, rights, late rework and the private leakage of status pressure. It does not copy the Program/curation story or any film/TV director plot; the shared reference structure is only the canonical Role World contract.\n\n## Season depth\n- 14 days × four phases = **56 unique beats**.\n- **Seven** evolving threads: artistic readability, body/consent, director–choreographer alignment, technical safety/integration, version/handoff/rework, ensemble power/note culture, and private recovery.\n- **Eight** delayed consequences.\n- **Five** private aftermath sequences.\n- All **15 authored prerequisite mails** are reused repeatedly as materialization provenance; there is no generic fallback.\n\n## Situated standing and authority\nSeven audiences hold different standing axes. Standing may diverge after the same choice and never becomes a global reputation score. Artistic standing cannot grant performer consent, HMS/technical approval, rights, employment, budget or wider mandate. Public success cannot retroactively legitimize an unsafe or coercive process.\n\n## History Go\nThe existing Edith Roger / Nationaltheatret task remains bounded historical context. It asks how scene instruction, choreography, ensemble and theatre space can shape each other over time; it cannot prescribe today's method, grant consent, approve safety or expand mandate.\n\n## Cross-role boundary\nReadiness remains \`candidate_when_shared_work_is_real\`. This Role World materializes **no** cross-role runtime or shared work object. A later cross-role link must prove genuinely shared work rather than proximity between directing, choreography, ensemble and production.\n\n## Fail-closed publication\nThe temporary materializer/workflow must pass the focused 56-beat gate, prerequisite compatibility, canonical generated-state parity, full Civication and repository diff cleanliness before permanent files are committed and TEMP controls are removed.\n\n## Six-part quality gate — 29/30\n| Dimension | Score | Evidence |\n| --- | ---: | --- |\n| Architecture and contracts | 5/5 | Existing model, grammar, plan, actors, surfaces, persistent work and authority remain intact. |\n| Content depth and specificity | 5/5 | 56 beats, seven threads, eight delayed consequences, five private aftermath arcs. |\n| Sociological realism | 5/5 | Power, body, consent, status, technical veto, version debt and private leakage are explicit. |\n| Provenance and state | 5/5 | Every beat uses one of the 15 authored source mails; waiting/handoff/bounded rework persists. |\n| Scope and runtime hygiene | 5/5 | One role only, no new runtime, no cross-role object without shared-work proof. |\n| Runtime evidence at publication | 4/5 | Exact-head PR CI supplies authoritative browser boot-smoke evidence. |\n\nTotal: **29/30**. No critical Role World gap is accepted.`);
